use aap::caps::state_read;

struct Node;

fn parse_urls(raw: &str) -> Vec<String> {
    let t = raw.trim();
    let mut out: Vec<String> = Vec::new();
    if t.starts_with('[') {
        // Extract double-quoted strings from a JSON-style array.
        let mut cur = String::new();
        let mut in_str = false;
        let mut esc = false;
        for c in t.chars() {
            if in_str {
                if esc {
                    cur.push(c);
                    esc = false;
                } else if c == '\\' {
                    esc = true;
                } else if c == '"' {
                    in_str = false;
                    let s = cur.trim().to_string();
                    if !s.is_empty() {
                        out.push(s);
                    }
                    cur.clear();
                } else {
                    cur.push(c);
                }
            } else if c == '"' {
                in_str = true;
            }
        }
        if !out.is_empty() {
            return out;
        }
    }
    for tok in t.split(|c: char| c == '\n' || c == '\r' || c == ',' || c.is_whitespace()) {
        let s = tok.trim().trim_matches(|c| c == '"' || c == '\'');
        if !s.is_empty() {
            out.push(s.to_string());
        }
    }
    out
}

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        let raw = state_read::get("subscriptions").or_else(|| state_read::get("urls"));
        let urls = match raw {
            Some(r) => parse_urls(&r),
            None => Vec::new(),
        };
        SubscriptionList { urls }
    }
}

export!(Node);
